use super::{fixtures as f,host::{self,structured},provider::{Provider,Reply}};
use numera_gen_mcp::compat::value::Value as NativeValue;
use serde_json::{Value,json};
use std::sync::{Arc,atomic::{AtomicUsize,Ordering}};

pub async fn run(){let(_,bytes)=f::image("png");for state in["failed","incomplete"]{host::scenario(10000,terminal(state,&bytes)).await;}for mode in["error","malformed-terminal","empty-terminal-id","blank-terminal-id"]{host::scenario(10000,uncertain(mode)).await;}for adapter in["openai-responses","gemini-interactions"]{for returned in[Some("other"),None,Some("owned")]{host::scenario(10000,identity(adapter,returned,&bytes)).await;}}host::scenario(10000,comfy_history()).await;}
fn config(directory:&std::path::Path,origin:&str,adapter:&str)->Value{let mut connection=f::connection(&format!("{origin}/v1"),adapter);connection["defaultModel"]=json!("image");let config=f::config(directory,json!({"local":connection}));assert_eq!(config["connections"]["local"]["requestTimeoutMs"],300000);assert_eq!(config["connections"]["local"]["discoveryTimeoutMs"],15000);config}
async fn checked(host:&host::Host,name:&str,args:Value)->Value{let result=host.call(name,args).await;let value=structured(&result);assert_eq!(result["isError"]==true,name=="generate_image"&&["failed","outcome_unknown"].iter().any(|s|value["status"]==*s),"SDK error flag must preserve structured receipt");value}
async fn terminal(state:&'static str,bytes:&[u8]){
    let work=f::workspace();let directory=f::directory(&work,&format!("transport-terminal-{state}"));let posts=Arc::new(AtomicUsize::new(0));let p=posts.clone();let encoded=base64::Engine::encode(&base64::engine::general_purpose::STANDARD,bytes);
    let wire=Provider::new(move|request,_|{let p=p.clone();let encoded=encoded.clone();async move{if request.method=="POST"{p.fetch_add(1,Ordering::SeqCst);}let data=json!({"response":{"id":"owned","status":state,"output":if state=="incomplete"{json!([{"type":"image_generation_call","status":"completed","result":encoded}])}else{json!([])}}});Ok(Reply::sse(format!("event: response.{state}\ndata: {data}\n\n")))}}).await;
    let config=config(&directory,&wire.origin,"openai-responses");let mut store=f::store(&config);let mut host=f::start(&directory,&config,"transport-audit").await;
    let args=json!({"prompt":"fixture","request_id":"sse"});let result=checked(&host,"generate_image",args.clone()).await;assert_eq!(result["generation_outcome"],state);assert_eq!(result["status"],if state=="failed"{"failed"}else{"partial"});if state=="incomplete"{f::saved(&result,bytes);}host.call("generate_image",args).await;assert_eq!(posts.load(Ordering::SeqCst),1);store.prepare(f::receipt("next","local","openai-images"),"next","fixture").unwrap();assert!(store.admit("next","local",1,1).unwrap());host.close().await.unwrap();drop(store);wire.close().await;
}
async fn uncertain(mode:&'static str){
    let work=f::workspace();let directory=f::directory(&work,&format!("transport-uncertain-{mode}"));let posts=Arc::new(AtomicUsize::new(0));let p=posts.clone();
    let wire=Provider::new(move|request,_|{let p=p.clone();async move{if request.method=="POST"{p.fetch_add(1,Ordering::SeqCst);}let frame=if mode=="error"{"event: error\ndata: {\"error\":\"synthetic\"}\n\n".into()}else{let mut response=json!({"status":"failed"});if mode=="empty-terminal-id"{response["id"]=json!("");}else if mode=="blank-terminal-id"{response["id"]=json!(" ");}format!("event: response.failed\ndata: {}\n\n",json!({"response":response}))};Ok(Reply::sse(frame))}}).await;
    let config=config(&directory,&wire.origin,"openai-responses");let mut host=f::start(&directory,&config,"transport-audit").await;let result=checked(&host,"generate_image",json!({"prompt":"fixture","request_id":"uncertain"})).await;assert_eq!(result["status"],"outcome_unknown");assert_eq!(result["outputs"],json!([]));assert_eq!(posts.load(Ordering::SeqCst),1);host.close().await.unwrap();wire.close().await;
}
async fn identity(adapter:&'static str,returned:Option<&'static str>,bytes:&[u8]){
    let work=f::workspace();let directory=f::directory(&work,&format!("transport-identity-{adapter}-{}",returned.unwrap_or("missing")));let posts=Arc::new(AtomicUsize::new(0));let p=posts.clone();let encoded=base64::Engine::encode(&base64::engine::general_purpose::STANDARD,bytes);
    let wire=Provider::new(move|request,_|{let p=p.clone();let encoded=encoded.clone();async move{if request.method=="POST"{p.fetch_add(1,Ordering::SeqCst);return Ok(Reply::json(json!({"id":"owned","status":"in_progress"})));}let mut value=json!({"status":"completed"});if let Some(id)=returned{value["id"]=json!(id);}if adapter=="openai-responses"{value["output"]=json!([{"type":"image_generation_call","status":"completed","result":encoded}]);}else{value["steps"]=json!([{"type":"model_output","content":[{"type":"image","data":encoded}]}]);}Ok(Reply::json(value))}}).await;
    let config=config(&directory,&wire.origin,adapter);let mut store=f::store(&config);let mut host=f::start(&directory,&config,"transport-audit").await;
    let first=checked(&host,"generate_image",json!({"prompt":"fixture","request_id":"waiting"})).await;let identity=f::identity(&config,"local",&directory).await;let mut saved=store.prepare(f::receipt("detached","local","openai-images"),"fixture",&identity).unwrap().1;assert!(store.admit("detached","local",4,4).unwrap());saved.value["status"]=NativeValue::from("running");saved.value["generation_outcome"]=NativeValue::from("running");saved.value["adapter"]=NativeValue::from(adapter);saved.value["upstream_job"]=NativeValue::parse(&json!({"id":"owned","kind":if adapter=="openai-responses"{"responses"}else{"interactions"}}).to_string()).unwrap();store.update(&mut saved).unwrap();store.release("detached",Some(&saved)).unwrap();
    let second=checked(&host,"get_job",json!({"request_id":"detached","refresh":true})).await;for result in[first,second]{if returned==Some("owned"){f::saved(&result,bytes);}else{assert_eq!(result["status"],"running");assert_eq!(result["outputs"],json!([]));assert!(result["errors"].as_array().unwrap().iter().any(|e|e["code"]=="invalid_response"));}}assert_eq!(posts.load(Ordering::SeqCst),1);host.close().await.unwrap();drop(store);wire.close().await;
}
async fn comfy_history(){
    let work=f::workspace();let directory=f::directory(&work,"transport-comfy-error-history");let views=Arc::new(AtomicUsize::new(0));let posts=Arc::new(AtomicUsize::new(0));let v=views.clone();let p=posts.clone();let wire=Provider::new(move|request,_|{let v=v.clone();let p=p.clone();async move{if request.path.starts_with("/view"){v.fetch_add(1,Ordering::SeqCst);}if request.method=="POST"{p.fetch_add(1,Ordering::SeqCst);}assert_eq!(request.method,"GET");assert_eq!(request.path,"/history/job");Ok(Reply::json(json!({"job":{"status":{"status_str":"error"},"outputs":{"save":{"images":[{"filename":"not-output.png","type":"input"}]}}}})))}}).await;
    let config=f::config(&directory,json!({"local":{"adapter":"comfyui","baseUrl":wire.origin,"auth":{"type":"none"},"discoveryTimeoutMs":2000,"requestTimeoutMs":2000,"workflow":{
        "graph":{"text":{"class_type":"CLIPTextEncode","inputs":{"text":"original"}},"sampler":{"class_type":"KSampler","inputs":{"seed":0,"batch_size":1}},"load":{"class_type":"LoadImage","inputs":{"image":"original.png","mask":"mask.png"}},"second":{"class_type":"LoadImage","inputs":{"image":"second.png"}},"save":{"class_type":"SaveImage","inputs":{"images":["sampler",0]}}},
        "bindings":{"prompt":{"node":"text","input":"text"},"seed":{"node":"sampler","input":"seed"},"count":{"node":"sampler","input":"batch_size"},"image":{"node":"load","input":"image"},"image_2":{"node":"second","input":"image"},"mask":{"node":"load","input":"mask"}},"outputNodes":["save"],"requireGpu":true
    }}}));
    {
        let identity=f::identity(&config,"local",&directory).await;
        let mut store=f::store(&config);
        let mut initial=f::receipt("history","local","comfyui");
        initial.value["status"]=NativeValue::from("running");initial.value["generation_outcome"]=NativeValue::from("running");
        initial.value["upstream_job"]=NativeValue::parse("{\"id\":\"job\",\"kind\":\"comfyui\"}").unwrap();
        let saved=store.prepare(initial,"hash",&identity).unwrap().1;store.release("history",Some(&saved)).unwrap();
    }
    let store=f::store(&config);let mut host=f::start(&directory,&config,"comfy-history-audit").await;let result=checked(&host,"get_job",json!({"request_id":"history","refresh":true})).await;assert_eq!(result["status"],"failed");assert_eq!(result["generation_outcome"],"failed");assert_eq!(result["outputs"],json!([]));assert!(result["errors"].as_array().unwrap().iter().any(|e|e["code"]=="provider_rejection"));assert!(f::as_json(&store.get("history").unwrap())["errors"].as_array().unwrap().iter().any(|e|e["code"]=="provider_rejection"));assert_eq!(views.load(Ordering::SeqCst),0);assert_eq!(posts.load(Ordering::SeqCst),0);host.close().await.unwrap();drop(store);wire.close().await;
}
